#!/usr/bin/env node
// pg-internals MCP server: PostgreSQL 18 internals knowledge + a live, disposable PostgreSQL 18 sandbox.
// Transport: stdio. Data: ./data (generated by app/scripts/export-for-mcp.mjs).
import fs from 'node:fs'
import path from 'node:path'
import { Worker } from 'node:worker_threads'
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js'
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js'
import { z } from 'zod'

const DIR = import.meta.dirname
const load = (f) => JSON.parse(fs.readFileSync(path.join(DIR, 'data', f), 'utf8'))
const { tracks: TRACKS = [], modules: MODULES, lessons: LESSONS } = load('lessons.json')
const { datasets: DATASETS = [], exercises: EXERCISES = [] } = fs.existsSync(path.join(DIR, 'data', 'cookbook.json')) ? load('cookbook.json') : {}
const REFERENCE = load('reference.json')
const NOTES = load('notes.json')
const { categories: GUIDE_CATEGORIES = [], rules: GUIDE_RULES = [] } = fs.existsSync(path.join(DIR, 'data', 'guide.json')) ? load('guide.json') : {}
const SITE = 'https://vivek-rm-14286.github.io/postgres-internals/'

/* ------------------------------------------------------------------ rendering */

const moduleTitle = (id) => MODULES.find((m) => m.id === id)?.title ?? id

function lessonMarkdown(l) {
  const p = l.production
  return [
    `# ${l.title}`,
    `${MODULES.find((m) => m.id === l.module)?.code ?? l.module} · ${moduleTitle(l.module)} · lesson ${l.order} · ${l.url}`,
    `## TL;DR\n${l.tldr.join(' ')}`,
    `## Mechanism (interactive visual on the site)\n**${l.visualizer.title}**: ${l.visualizer.caption}`,
    `## Playground\nSetup:\n\`\`\`sql\n${l.playground.setup.trim()}\n\`\`\`` + (l.playground.extensions?.length ? `\nExtensions: ${l.playground.extensions.join(', ')}` : ''),
    ...l.playground.presets.map((pr, i) => `### ${i + 1}. ${pr.label}\n\`\`\`sql\n${pr.sql.trim()}\n\`\`\`${pr.note ? `\nLook for: ${pr.note}` : ''}`),
    `## In production: ${p.title}\n${p.context}\n\n**Problem.** ${p.problem}\n\n**Solution.** ${p.solution}` + (p.sql ? `\n\`\`\`sql\n${p.sql.trim()}\n\`\`\`` : '') + `\n\n**Outcome.** ${p.outcome}`,
    `## Pitfalls\n` + l.pitfalls.map((x) => `### ${x.title}\n- Symptom: ${x.symptom}\n- Why: ${x.cause}\n- Fix: ${x.fix}` + (x.sql ? `\n\`\`\`sql\n${x.sql.trim()}\n\`\`\`` : '')).join('\n'),
    `## Key pointers\n` + l.pointers.map((x) => `- ${x}`).join('\n'),
  ].join('\n\n')
}

const sitePath = (p) => `${SITE}#${p}`
const guideCategory = (id) => GUIDE_CATEGORIES.find((c) => c.id === id)?.title ?? id
/** One Production guide rule as markdown: the rule, why, the pattern to avoid and the one to use, exceptions, lessons. */
function ruleMarkdown(r, heading = '###') {
  return [
    `${heading} ${r.rule}`,
    `id: guide:${r.id} · ${guideCategory(r.category)} · protects: ${r.impact}`,
    `**Why.** ${r.why}`,
    r.avoid ? `**Avoid**\n\`\`\`sql\n${r.avoid.trim()}\n\`\`\`` : '',
    r.prefer ? `**Prefer**\n\`\`\`sql\n${r.prefer.trim()}\n\`\`\`` : '',
    r.unless ? `**Unless.** ${r.unless}` : '',
    `Lessons: ${r.learn.map((p) => { const l = LESSONS.find((x) => `/${x.module}/${x.slug}` === p); return l ? `${l.title} (get_lesson ${l.slug})` : sitePath(p) }).join('; ')}`,
  ].filter(Boolean).join('\n\n')
}
const ruleText = (r) => [r.rule, r.why, r.avoid ?? '', r.prefer ?? '', r.unless ?? '', guideCategory(r.category), r.id.replace(/-/g, ' '),
  ...r.learn.map((p) => LESSONS.find((x) => `/${x.module}/${x.slug}` === p)?.title ?? '')].join('\n')

const lessonText = (l) => [l.title, l.tldr.join(' '), l.visualizer.title, l.visualizer.caption,
  ...l.playground.presets.flatMap((p) => [p.label, p.note ?? '', p.sql]), l.production.title, l.production.problem, l.production.solution,
  ...l.pitfalls.flatMap((p) => [p.title, p.symptom, p.cause, p.fix]), ...l.pointers].join('\n')

/* ------------------------------------------------------------------ search (BM25) */

const tokenize = (s) => s.toLowerCase().match(/[a-z0-9_]+(?:\.[a-z0-9_]+)*/g) ?? []
const docs = []
for (const r of GUIDE_RULES) docs.push({ id: `guide:${r.id}`, kind: 'guideline', title: `${r.rule} (production guideline, ${guideCategory(r.category)})`, text: ruleText(r), boost: 1.6 })
for (const l of LESSONS) docs.push({ id: `lesson:${l.slug}`, kind: 'lesson', title: `${l.title} (lesson ${l.module}/${l.slug})`, text: lessonText(l), boost: 1.4 })
for (const t of REFERENCE) t.rows.forEach((r, i) => docs.push({ id: `ref:${t.id}:${i}`, kind: 'reference', title: `${r[0]} — ${t.title}`, text: `${t.title}\n` + t.columns.map((c, j) => `${c}: ${r[j] ?? ''}`).join('\n'), boost: 1.2 }))
for (const e of EXERCISES) docs.push({ id: `exercise:${e.id}`, kind: 'exercise', title: `${e.title.replace(/[*`]/g, '')} (${e.level} exercise, ${e.dataset})`, text: [e.title, e.topic, e.task, e.hint ?? '', e.explanation].join('\n'), boost: 1.1 })
NOTES.forEach((n, i) => docs.push({ id: `note:${i}`, kind: n.kind === 'docs' ? 'docs' : 'lesson-plan', title: [n.section, n.title].filter((x, j, a) => x && a.indexOf(x) === j).join(' › '), text: n.text, boost: 1 }))

const df = new Map()
let avgLen = 0
for (const d of docs) {
  d.tf = new Map()
  const toks = tokenize(d.title + ' ' + d.title + ' ' + d.text)
  for (const t of toks) d.tf.set(t, (d.tf.get(t) ?? 0) + 1)
  d.len = toks.length
  avgLen += d.len
  for (const t of d.tf.keys()) df.set(t, (df.get(t) ?? 0) + 1)
}
avgLen /= docs.length

function search(query, kind, limit) {
  const q = [...new Set(tokenize(query))]
  const phrase = query.toLowerCase().trim()
  const N = docs.length, k1 = 1.2, b = 0.75
  const scored = []
  for (const d of docs) {
    if (kind !== 'all' && d.kind !== kind) continue
    let s = 0
    for (const t of q) {
      const f = d.tf.get(t)
      if (!f) continue
      const idf = Math.log(1 + (N - df.get(t) + 0.5) / (df.get(t) + 0.5))
      s += idf * (f * (k1 + 1)) / (f + k1 * (1 - b + b * d.len / avgLen))
    }
    if (s > 0) {
      if (phrase.length > 3 && (d.title + ' ' + d.text).toLowerCase().includes(phrase)) s *= 1.5
      scored.push([s * d.boost, d])
    }
  }
  return scored.sort((a, b) => b[0] - a[0]).slice(0, limit).map(([, d]) => d)
}

function snippet(text, query, len = 280) {
  const lower = text.toLowerCase()
  const terms = tokenize(query).filter((t) => t.length > 2)
  let at = -1
  for (const t of terms) { at = lower.indexOf(t); if (at >= 0) break }
  const start = Math.max(0, at - 80)
  return (start > 0 ? '…' : '') + text.slice(start, start + len).replace(/\s+/g, ' ').trim() + (start + len < text.length ? '…' : '')
}

function readDoc(id) {
  if (id.startsWith('lesson:')) { const l = LESSONS.find((x) => x.slug === id.slice(7)); return l && lessonMarkdown(l) }
  if (id.startsWith('guide:')) { const r = GUIDE_RULES.find((x) => x.id === id.slice(6)); return r && ruleMarkdown(r, '#') }
  if (id.startsWith('ref:')) {
    const [, tid, i] = id.split(':'); const t = REFERENCE.find((x) => x.id === tid); const r = t?.rows[+i]
    return r && `# ${r[0]} (${t.title})\n\n` + t.columns.map((c, j) => `- **${c}**: ${r[j] ?? ''}`).join('\n')
  }
  if (id.startsWith('exercise:')) {
    const e = EXERCISES.find((x) => x.id === id.slice(9)); if (!e) return undefined
    const d = DATASETS.find((x) => x.id === e.dataset)
    return [`# ${e.title} (${e.level}, ${e.topic})`, `Dataset **${d?.title}**: ${d?.description}`, ...(d?.tables ?? []).map((t) => `- ${t.name}(${t.columns})`),
      `## Task\n${e.task}`, e.hint ? `Hint: ${e.hint}` : '', `## Reference solution\n\`\`\`sql\n${e.solution.trim()}\n\`\`\``, e.explanation,
      `## Dataset setup (run it with run_sql to try the exercise)\n\`\`\`sql\n${d?.setup.trim()}\n\`\`\``,
      `Practise interactively: https://vivek-rm-14286.github.io/postgres-internals/#/cookbook/${e.id}`].filter(Boolean).join('\n\n')
  }
  if (id.startsWith('note:')) { const n = NOTES[+id.slice(5)]; return n && `# ${[n.section, n.title].filter(Boolean).join(' › ')}\n\n${n.text}` }
  return undefined
}

/* ------------------------------------------------------------------ sandbox sessions */

const MAX_SESSIONS = 8
const sessions = new Map() // name -> { worker, pending: Map, lastUsed }
let seq = 0

function session(name, withPostgis = false) {
  let s = sessions.get(name)
  if (s && withPostgis && !s.postgis) throw new Error(`session "${name}" was started without PostGIS; call reset_sandbox first or use a new session name`)
  if (!s) {
    if (sessions.size >= MAX_SESSIONS) {
      const [oldest] = [...sessions.entries()].sort((a, b) => a[1].lastUsed - b[1].lastUsed)[0]
      dropSession(oldest)
    }
    const worker = new Worker(path.join(DIR, 'worker.mjs'))
    s = { worker, pending: new Map(), lastUsed: Date.now(), postgis: withPostgis }
    worker.on('message', (m) => { s.pending.get(m.id)?.resolve(m); s.pending.delete(m.id) })
    worker.on('error', (e) => { for (const p of s.pending.values()) p.reject(e); s.pending.clear(); sessions.delete(name) })
    worker.unref()
    sessions.set(name, s)
  }
  s.lastUsed = Date.now()
  return s
}

function dropSession(name) {
  const s = sessions.get(name)
  if (!s) return false
  sessions.delete(name)
  for (const p of s.pending.values()) p.reject(new Error('session reset'))
  void s.worker.terminate()
  return true
}

function runSql(name, sql, timeoutMs, withPostgis = false) {
  const s = session(name, withPostgis)
  const id = ++seq
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      s.pending.delete(id)
      reject(new Error(`timed out after ${timeoutMs} ms; session "${name}" was reset (its data is gone)`))
      dropSession(name)
    }, timeoutMs)
    s.pending.set(id, { resolve: (m) => { clearTimeout(timer); resolve(m) }, reject: (e) => { clearTimeout(timer); reject(e) } })
    s.worker.postMessage({ id, sql, withPostgis: s.postgis })
  })
}

const cell = (v) => {
  if (v === null || v === undefined) return 'NULL'
  if (v instanceof Date) return v.toISOString()
  if (v instanceof Uint8Array) return '\\x' + Buffer.from(v.subarray(0, 64)).toString('hex') + (v.length > 64 ? '…' : '')
  if (typeof v === 'object') return JSON.stringify(v)
  return String(v)
}

function formatResult(r, maxRows, maxCell = 200) {
  if (r.fields.length === 0) return r.affectedRows !== undefined ? `(statement ${r.statement}: ${r.affectedRows} row(s) affected)` : `(statement ${r.statement}: ok)`
  if (r.fields.length === 1 && r.fields[0] === 'QUERY PLAN') return r.rows.map((x) => cell(x[0])).join('\n')
  const rows = r.rows.slice(0, maxRows).map((row) => row.map((v) => { const c = cell(v).replace(/\n/g, '\\n'); return c.length > maxCell ? c.slice(0, maxCell) + '…' : c }))
  const w = r.fields.map((f, j) => Math.max(f.length, ...rows.map((row) => row[j].length)))
  const line = (vals) => vals.map((v, j) => v.padEnd(w[j])).join(' | ').trimEnd()
  const out = [line(r.fields), w.map((n) => '-'.repeat(n)).join('-+-'), ...rows.map(line)]
  out.push(`(${r.rows.length} row${r.rows.length === 1 ? '' : 's'}${r.rows.length > maxRows ? `, showing ${maxRows}` : ''})`)
  return out.join('\n')
}

/* ------------------------------------------------------------------ MCP server */

const server = new McpServer(
  { name: 'pg-internals', version: '1.3.0' },
  {
    instructions:
      `PostgreSQL 18 from fundamentals to internals: ${LESSONS.length} lessons in three tracks (Fundamentals: SQL from first query to production patterns; ` +
      'Internals: storage, MVCC, locking, planner, indexes, WAL, replication, vacuum; Ecosystem: pgvector, TimescaleDB, distributed PostgreSQL), ' +
      `${EXERCISES.length} graded SQL exercises with reference solutions, complete reference ` +
      'tables (every GUC, catalog, view, wait event, lock mode, SQLSTATE, SQL command, data type), distilled docs notes, and a live ' +
      `PostgreSQL 18 sandbox, plus a Production guide of ${GUIDE_RULES.length} rules for production and scalable services (queries, schema, indexes, ` +
      'transactions, schema changes, connections, vacuum, observability, reliability, security, scaling). Before you write or review SQL, a schema, ' +
      'a migration or database configuration meant for production, call `production_guidelines` for the relevant categories and apply the rules; ' +
      'cite the rule id when you rely on one. Use `search` first for everything else, then `read` or `get_lesson`. Use `run_sql` to verify behaviour (EXPLAIN, pageinspect, ' +
      'pg_locks, xmin/xmax) instead of guessing. The sandbox is a single-backend in-memory PGlite: no replication, no second connection.',
  },
)

const text = (t) => ({ content: [{ type: 'text', text: t }] })
const ro = { readOnlyHint: true, openWorldHint: false }

server.registerTool('search', {
  title: 'Search PostgreSQL internals knowledge',
  description: 'Ranked full-text search over lessons, graded SQL exercises (beginner → expert, with reference solutions), reference tables (GUCs, catalogs, views, wait events, lock modes, SQLSTATEs, SQL commands, data types, functions, glossary) and distilled PostgreSQL 18 docs notes. Returns ids for `read`.',
  inputSchema: {
    query: z.string().min(1).describe('Keywords, e.g. "HOT update fillfactor", "autovacuum_vacuum_scale_factor", "40P01", "SIRead"'),
    kind: z.enum(['all', 'guideline', 'lesson', 'exercise', 'reference', 'docs', 'lesson-plan']).default('all').describe('Restrict to one source kind'),
    limit: z.number().int().min(1).max(30).default(8),
  },
  annotations: ro,
}, async ({ query, kind, limit }) => {
  const hits = search(query, kind, limit)
  if (!hits.length) return text(`No results for "${query}". Try fewer or different keywords.`)
  return text(hits.map((d, i) => `${i + 1}. [${d.kind}] ${d.title}\n   id: ${d.id}\n   ${snippet(d.text, query)}`).join('\n\n'))
})

server.registerTool('read', {
  title: 'Read a search result in full',
  description: 'Return the full text of a `search` hit by its id (guide:…, lesson:…, exercise:…, ref:…, note:…).',
  inputSchema: { id: z.string().describe('An id returned by search') },
  annotations: ro,
}, async ({ id }) => text(readDoc(id) ?? `Unknown id "${id}".`))

server.registerTool('production_guidelines', {
  title: 'Production guidelines for PostgreSQL',
  description:
    `Recommendations for production and scalable services (${GUIDE_RULES.length} rules). Each rule: what to do, why (the failure it prevents), the pattern to avoid, ` +
    'the pattern to use, exceptions, and the lessons that explain the mechanism. Call this before writing or reviewing queries, schema, indexes, migrations, ' +
    'connection or server settings for a real service. With no arguments it returns the checklist: every rule as one line, grouped by category. ' +
    `Pass a category (${GUIDE_CATEGORIES.map((c) => `${c.id}: ${c.title}`).join('; ')}) and/or a query to get matching rules in full.`,
  inputSchema: {
    category: z.enum(GUIDE_CATEGORIES.length ? GUIDE_CATEGORIES.map((c) => c.id) : ['none']).optional().describe('Return the rules of one category in full'),
    query: z.string().optional().describe('Keywords; every word must appear in the rule, e.g. "pagination", "lock_timeout", "foreign key index"'),
    impact: z.enum(['correctness', 'performance', 'availability', 'security', 'operability']).optional().describe('Only rules that mainly protect this'),
    format: z.enum(['full', 'checklist']).optional().describe('full = rule, why, avoid/prefer SQL, exceptions; checklist = one line per rule. Default: full when category or query is given, otherwise checklist'),
  },
  annotations: ro,
}, async ({ category, query, impact, format }) => {
  const words = (query ?? '').toLowerCase().split(/\s+/).filter(Boolean)
  const rules = GUIDE_RULES.filter((r) => (!category || r.category === category) && (!impact || r.impact === impact) && words.every((w) => ruleText(r).toLowerCase().includes(w)))
  if (!rules.length) return text('No production guideline matches. Call production_guidelines with no arguments for the full checklist, or use search.')
  const full = (format ?? (category || words.length ? 'full' : 'checklist')) === 'full'
  const groups = GUIDE_CATEGORIES.map((c) => ({ c, rs: rules.filter((r) => r.category === c.id) })).filter((g) => g.rs.length)
  const body = groups.map(({ c, rs }) => `## ${c.title} (${c.id})\n${c.blurb}\n\n` + (full ? rs.map((r) => ruleMarkdown(r)).join('\n\n---\n\n') : rs.map((r) => `- ${r.rule} [${r.impact}] (guide:${r.id})`).join('\n'))).join('\n\n')
  return text(`# PostgreSQL production guidelines: ${rules.length} of ${GUIDE_RULES.length} rules\n` +
    (full ? '' : 'One line per rule. For the reasoning and SQL of a rule, call `read` with its id, or call this tool with a category or query.\n') + `Site: ${sitePath('/guide')}\n\n` + body)
})

server.registerTool('list_lessons', {
  title: 'List lessons',
  description: 'List all tracks, modules and lessons (slug, title), optionally for one module.',
  inputSchema: { module: z.enum(MODULES.map((m) => m.id)).optional() },
  annotations: ro,
}, async ({ module }) => text(MODULES.filter((m) => !module || m.id === module).map((m) =>
  `## ${m.code ?? m.id} · ${m.title}${m.track ? ` (${TRACKS.find((t) => t.id === m.track)?.title ?? m.track})` : ''} · module id ${m.id}\n${m.blurb}\n` + LESSONS.filter((l) => l.module === m.id).map((l) => `- ${l.slug}: ${l.title} — ${l.tldr[0]}`).join('\n')).join('\n\n')))

server.registerTool('get_lesson', {
  title: 'Get a lesson',
  description: 'Full lesson as markdown: TL;DR, mechanism, runnable playground SQL with what to look for, a production scenario, pitfalls (symptom / why / fix) and key pointers.',
  inputSchema: { slug: z.string().describe('Lesson slug from list_lessons, e.g. "hot-fillfactor", "explain-analyze"') },
  annotations: ro,
}, async ({ slug }) => {
  const l = LESSONS.find((x) => x.slug === slug)
  return text(l ? lessonMarkdown(l) : `Unknown lesson "${slug}". Call list_lessons for slugs.`)
})

server.registerTool('lookup_reference', {
  title: 'Look up reference tables',
  description: `Filter one of the reference tables by text (matches any column). Tables: ${REFERENCE.map((t) => `${t.id} (${t.rows.length})`).join(', ')}. Omit table to search all.`,
  inputSchema: {
    query: z.string().min(1).describe('e.g. "work_mem", "ShareUpdateExclusive", "23505", "pg_stat_io", "BufferPin"'),
    table: z.enum(REFERENCE.map((t) => t.id)).optional(),
    limit: z.number().int().min(1).max(100).default(20),
  },
  annotations: ro,
}, async ({ query, table, limit }) => {
  const q = query.toLowerCase()
  const out = []
  for (const t of REFERENCE) {
    if (table && t.id !== table) continue
    const exact = t.rows.filter((r) => r[0].toLowerCase() === q)
    const rest = t.rows.filter((r) => r[0].toLowerCase() !== q && r.some((c) => c.toLowerCase().includes(q)))
    for (const r of [...exact, ...rest]) out.push(`[${t.id}] ` + t.columns.map((c, j) => `${c}: ${r[j] ?? ''}`).join(' | '))
  }
  if (!out.length) return text(`No reference rows match "${query}".`)
  return text(out.slice(0, limit).join('\n') + (out.length > limit ? `\n… ${out.length - limit} more; narrow the query or set table.` : ''))
})

server.registerTool('run_sql', {
  title: 'Run SQL on a live PostgreSQL 18 sandbox',
  description:
    'Execute SQL on an in-memory PostgreSQL 18 (PGlite) session. Statements run one by one like psql (each autocommits unless you BEGIN). ' +
    'State persists per `session` name until reset. Output: result tables, EXPLAIN plans, NOTICE/INFO messages (VACUUM VERBOSE, RAISE), and errors with SQLSTATE. ' +
    'CREATE EXTENSION works for: pageinspect, pg_visibility, pg_freespacemap, pg_buffercache, pg_walinspect, pg_stat_statements, pg_trgm, btree_gin, btree_gist, ' +
    'bloom, amcheck, hstore, ltree, citext, pgcrypto, tablefunc, pg_surgery, tsm_system_rows, "uuid-ossp", cube, earthdistance, fuzzystrmatch, intarray, isn, lo, ' +
    'seg, unaccent, dict_int, dict_xsyn, auto_explain, tcn, moddatetime, vector; and postgis when with_postgis is true. Limits: one backend (no concurrent sessions inside one sandbox), no replication.',
  inputSchema: {
    sql: z.string().min(1),
    session: z.string().regex(/^[\w-]{1,40}$/).default('default').describe('Sandbox name; separate names are fully independent databases'),
    max_rows: z.number().int().min(1).max(1000).default(50),
    timeout_ms: z.number().int().min(1000).max(300000).default(30000),
    with_postgis: z.boolean().default(false).describe('Start this session with PostGIS 3.6 available (CREATE EXTENSION postgis). Adds ~4 s to the first call; set it on the first call for a session.'),
  },
  annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: false, openWorldHint: false },
}, async ({ sql, session: name, max_rows, timeout_ms, with_postgis }) => {
  try {
    const m = await runSql(name, sql, timeout_ms, with_postgis)
    const parts = []
    if (m.notices.length) parts.push(m.notices.join('\n'))
    for (const r of m.results) parts.push(formatResult(r, max_rows))
    if (m.error) {
      const e = m.error
      parts.push(`ERROR${e.code ? ` ${e.code}` : ''}: ${e.message}` + (e.detail ? `\nDETAIL: ${e.detail}` : '') + (e.hint ? `\nHINT: ${e.hint}` : '') +
        (e.statement ? `\n(in statement ${e.statement} of ${m.statements}: ${e.sql.slice(0, 200)}; later statements did not run)` : ''))
    }
    parts.push(`[session "${name}" · ${m.ms.toFixed(1)} ms]`)
    return { content: [{ type: 'text', text: parts.join('\n\n') }], isError: Boolean(m.error) }
  } catch (e) {
    return { content: [{ type: 'text', text: `Sandbox error: ${e.message}` }], isError: true }
  }
})

server.registerTool('reset_sandbox', {
  title: 'Reset a sandbox session',
  description: 'Discard a sandbox session and all its data. The next run_sql on that name starts a fresh PostgreSQL 18.',
  inputSchema: { session: z.string().default('default') },
  annotations: { readOnlyHint: false, destructiveHint: true, idempotentHint: true, openWorldHint: false },
}, async ({ session: name }) => text(dropSession(name) ? `Session "${name}" reset.` : `No session named "${name}" was running.`))

await server.connect(new StdioServerTransport())
